export const FACILITIES = FACILITIES_DATA.map((f) => f.name);

export const FACILITY_BY_NAME = Object.fromEntries(
  FACILITIES_DATA.map((f) => [f.name, f])
);

export const FACILITIES_BY_BLOCK = FACILITIES_DATA.reduce((acc, f) => {
  if (!acc[f.block]) acc[f.block] = [];
  acc[f.block].push(f.name);
  return acc;
}, {});

export const FACILITY_OBJECTS_BY_BLOCK = FACILITIES_DATA.reduce((acc, f) => {
  if (!acc[f.block]) acc[f.block] = [];
  acc[f.block].push(f);
  return acc;
}, {});

export const VERIFIER_ACCOUNTS = FACILITIES_DATA.map((f) => ({
  username: f.username,
  facility: f.name,
  block: f.block,
  type: f.type,
  category: f.category,
}));

if (typeof module !== "undefined" && module.exports) {
  module.exports = {
    FACILITIES_DATA,
    FACILITIES,
    FACILITY_BY_NAME,
    FACILITIES_BY_BLOCK,
    FACILITY_OBJECTS_BY_BLOCK,
    VERIFIER_ACCOUNTS,
  };
}
